#!/usr/bin/env python3
"""Dialogue script parser that converts a text script into a structured JSON graph and DOT visualization."""

import json
import re


def parse_script(text: str) -> dict:
    """Parse a dialogue script into a graph with nodes and edges.

    Args:
        text: The script content as a string.

    Returns:
        A dict with 'nodes' (list of node dicts) and 'edges' (list of edge dicts).
    """
    nodes = []
    edges = []
    node_ids = set()

    lines = text.strip().split('\n')
    current_block_id = None
    block_lines = []

    def flush_block():
        nonlocal current_block_id, block_lines
        if current_block_id is None:
            return
        _process_block(current_block_id, block_lines, nodes, edges, node_ids)
        current_block_id = None
        block_lines = []

    for line in lines:
        line = line.rstrip()
        # Detect block headers like [Start]
        header_match = re.match(r'^\[(\w+)\]$', line.strip())
        if header_match:
            flush_block()
            current_block_id = header_match.group(1)
            continue
        if line.strip() == '':
            continue
        if current_block_id is not None:
            block_lines.append(line.strip())

    # Flush the last block
    flush_block()

    # Add terminal nodes that are referenced but not defined (like "End")
    referenced_targets = set()
    for edge in edges:
        referenced_targets.add(edge['to'])
    for target in referenced_targets:
        if target not in node_ids:
            nodes.append({
                'id': target,
                'text': '',
                'speaker': '',
                'type': 'line'
            })
            node_ids.add(target)

    return {'nodes': nodes, 'edges': edges}


def _process_block(block_id: str, block_lines: list, nodes: list, edges: list, node_ids: set):
    """Process a single block (header + its content lines) into nodes and edges."""
    if not block_lines:
        # Empty block — still create a node
        nodes.append({
            'id': block_id,
            'text': '',
            'speaker': '',
            'type': 'line'
        })
        node_ids.add(block_id)
        return

    # Check if this block contains numbered choices
    choice_pattern = re.compile(r'^(\d+)\.\s+(.+?)\s*->\s*(\w+)$')
    # Check if this block is a dialogue line: Speaker: text -> Target
    dialogue_pattern = re.compile(r'^(\w[\w\s]*?):\s+(.+?)\s*->\s*(\w+)$')

    # Determine block type by checking all lines
    all_choices = True
    for bl in block_lines:
        if not choice_pattern.match(bl):
            all_choices = False
            break

    if all_choices and len(block_lines) >= 1:
        # Choice node
        nodes.append({
            'id': block_id,
            'text': '',
            'speaker': '',
            'type': 'choice'
        })
        node_ids.add(block_id)
        for bl in block_lines:
            m = choice_pattern.match(bl)
            if m:
                choice_text = m.group(2).strip()
                target = m.group(3).strip()
                edges.append({
                    'from': block_id,
                    'to': target,
                    'text': choice_text
                })
    else:
        # Dialogue/narration line(s)
        for bl in block_lines:
            dm = dialogue_pattern.match(bl)
            if dm:
                speaker = dm.group(1).strip()
                text = dm.group(2).strip()
                target = dm.group(3).strip()
                nodes.append({
                    'id': block_id,
                    'text': text,
                    'speaker': speaker,
                    'type': 'line'
                })
                node_ids.add(block_id)
                edges.append({
                    'from': block_id,
                    'to': target,
                    'text': ''
                })
            else:
                # Fallback: treat as a line node with no target
                nodes.append({
                    'id': block_id,
                    'text': bl,
                    'speaker': '',
                    'type': 'line'
                })
                node_ids.add(block_id)


def generate_dot(graph: dict) -> str:
    """Generate a DOT format visualization from the graph."""
    lines = ['digraph dialogue {']
    lines.append('    rankdir=TB;')
    lines.append('    node [shape=box, style=filled];')
    lines.append('')

    for node in graph['nodes']:
        node_id = node['id']
        label_parts = [node_id]
        if node['speaker']:
            label_parts.append(f"{node['speaker']}: {node['text']}")
        elif node['text']:
            label_parts.append(node['text'])
        label = '\\n'.join(label_parts)
        # Escape quotes in label
        label = label.replace('"', '\\"')

        if node['type'] == 'choice':
            color = 'lightyellow'
            shape = 'diamond'
        elif node['id'] == 'End':
            color = 'lightcoral'
            shape = 'doublecircle'
        else:
            color = 'lightblue'
            shape = 'box'

        lines.append(f'    "{node_id}" [label="{label}", fillcolor="{color}", shape="{shape}"];')

    lines.append('')

    for edge in graph['edges']:
        edge_label = edge['text'].replace('"', '\\"')
        if edge_label:
            lines.append(f'    "{edge["from"]}" -> "{edge["to"]}" [label="{edge_label}"];')
        else:
            lines.append(f'    "{edge["from"]}" -> "{edge["to"]}";')

    lines.append('}')
    return '\n'.join(lines)


def validate_graph(graph: dict) -> list:
    """Validate the graph constraints. Returns a list of issues found."""
    issues = []
    node_ids = {n['id'] for n in graph['nodes']}

    # Find the first node
    if not graph['nodes']:
        issues.append('No nodes found')
        return issues

    first_node_id = graph['nodes'][0]['id']

    # Build adjacency list
    adjacency = {}
    for node in graph['nodes']:
        adjacency[node['id']] = []
    for edge in graph['edges']:
        if edge['from'] in adjacency:
            adjacency[edge['from']].append(edge['to'])

    # Check all nodes reachable from first node
    visited = set()
    stack = [first_node_id]
    while stack:
        current = stack.pop()
        if current in visited:
            continue
        visited.add(current)
        for neighbor in adjacency.get(current, []):
            if neighbor not in visited:
                stack.append(neighbor)

    unreachable = node_ids - visited
    if unreachable:
        issues.append(f'Unreachable nodes: {unreachable}')

    # Check all edge targets exist
    for edge in graph['edges']:
        if edge['to'] not in node_ids:
            issues.append(f"Edge target '{edge['to']}' does not exist")

    # Check multiple paths can lead to "End"
    end_edges = [e for e in graph['edges'] if e['to'] == 'End']
    if len(end_edges) < 2:
        issues.append(f'Only {len(end_edges)} path(s) lead to End (expected multiple)')

    return issues


def main():
    # Read the script
    with open('/app/script.txt', 'r') as f:
        text = f.read()

    # Parse
    graph = parse_script(text)

    # Validate
    issues = validate_graph(graph)
    if issues:
        print('Validation issues:')
        for issue in issues:
            print(f'  - {issue}')
    else:
        print('Validation passed: all constraints satisfied.')

    # Write JSON
    with open('/app/dialogue.json', 'w') as f:
        json.dump(graph, f, indent=2)
    print(f'Written dialogue.json with {len(graph["nodes"])} nodes and {len(graph["edges"])} edges.')

    # Write DOT
    dot_content = generate_dot(graph)
    with open('/app/dialogue.dot', 'w') as f:
        f.write(dot_content)
    print('Written dialogue.dot visualization.')


if __name__ == '__main__':
    main()

